mkdir -p /var/www/drawspy && cd /var/www/drawspy
cat << 'EOF_DS' | base64 -d | tar -xz































































































































































































































































































































































































































































































































































































EOF_DS

pnpm install
pnpm --filter @drawspy/server build

pm2 delete drawspy-server 2>/dev/null || true
pm2 start ecosystem.config.cjs --env production
pm2 save

cat << 'EOF_NG' > /etc/nginx/sites-available/drawspy
server {
    listen 80;
    server_name api.drawspy.com;

    location / {
        proxy_pass http://127.0.0.1:3001;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_cache_bypass $http_upgrade;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
EOF_NG

ln -sf /etc/nginx/sites-available/drawspy /etc/nginx/sites-enabled/
rm -f /etc/nginx/sites-enabled/default || true
nginx -t && systemctl reload nginx

certbot --nginx -d api.drawspy.com --non-interactive --agree-tos -m admin@drawspy.com || true
echo '🎉 DRAWSPY CANLI SUNUCU BAŞARIYLA KURULDU VE BAŞLATILDI!'
